#!/usr/bin/env node
// Builds the single-file bundle for artifacts and mini apps into kvcc/bundle/dist/.
// CSS is derived from registry/*.module.css (class names scoped to kv-<id>__<class>), so upstream updates flow through.
// Hand-written inputs: kvcc/bundle/src/{extras.css,behaviors.js,demo.html}.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const src = join(root, "kvcc", "bundle", "src");
const dist = join(root, "kvcc", "bundle", "dist");

const COMPONENTS = [
  "button", "input", "textarea", "checkbox", "switch", "badge", "card", "tabs",
  "alert", "progress", "skeleton", "metric-card", "dialog", "toast", "tooltip",
  "select", "sortable-data-table", "bar-chart", "sparkline",
  "app-shell",
];

const FONTS_URL = "https://fonts.googleapis.com/css2?family=Geist:wght@400;500&family=Inter:wght@400;500&display=swap";

const read = path => readFileSync(path, "utf8");

// Registry CSS leans on the font tokens' variable-font names; Google Fonts serves plain family names.
const fontOverride = `*, *::before, *::after { box-sizing: border-box; }
:root { --font-display: "Geist", sans-serif; --font-body: "Inter", sans-serif; }
body { margin: 0; background: var(--background); color: var(--foreground); font-family: var(--font-body); font-size: var(--text-base); line-height: var(--leading-body); letter-spacing: var(--tracking-body); -webkit-font-smoothing: antialiased; }
h1, h2, h3 { font-family: var(--font-display); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); }`;

// Prefix every class selector and keyframe name with the component id. Strips comments first so prose never matches.
const scope = (id, css) => {
  // CSS modules wrap theme selectors in :global(...); plain CSS needs them bare or the whole rule is dropped.
  const clean = css.replace(/\/\*[\s\S]*?\*\//g, "").replace(/:global\(([^)]*)\)/g, "$1");
  const keyframes = [...clean.matchAll(/@keyframes\s+([\w-]+)/g)].map(m => m[1]);
  let out = clean.replace(/\.([A-Za-z_][\w-]*)/g, (_, name) => `.kv-${id}__${name}`);
  for (const name of keyframes) out = out.replace(new RegExp(`(?<![\\w-])${name}(?![\\w-])`, "g"), `kv-${id}__${name}`);
  return out.replace(/\n{2,}/g, "\n").trim();
};

const componentCss = COMPONENTS.map(id => {
  // Extensions live beside the skill; everything else comes from the upstream registry.
  const path = [join(root, "registry", "components", id, `${id}.module.css`), join(root, "kvcc", "extensions", id, `${id}.module.css`)].find(existsSync);
  if (!path) throw new Error(`Missing CSS for "${id}"`);
  return `/* ${id} */\n${scope(id, read(path))}`;
}).join("\n\n");

const tokenCss = [read(join(root, "registry", "foundation.css")), read(join(root, "kvcc", "theme.css"))].join("\n");
const fontImport = `@import url("${FONTS_URL}");`;
const css = [
  `/* kvcc bundle. Generated by kvcc/scripts/build-bundle.mjs. Do not edit. */`,
  fontImport,
  tokenCss, fontOverride, componentCss, read(join(src, "extras.css")),
].join("\n\n");

// behaviors.js defines window.kvcc; the rest extend it, so order matters.
const JS_FILES = ["behaviors.js", "select.js", "table.js", "charts.js", "app-shell.js"];
const js = JS_FILES.map(f => read(join(src, f))).join("\n");
const demo = read(join(src, "demo.html"));
const demoJs = read(join(src, "demo-data.js"));

mkdirSync(dist, { recursive: true });
writeFileSync(join(dist, "kvcc.css"), css);
writeFileSync(join(dist, "kvcc.js"), js);

// Single file: <style> and <script> inlined into the demo, which doubles as the starter template.
const page = demo
  .replace("/*__KVCC_CSS__*/", () => css.replace(fontImport + "\n\n", ""))
  .replace("/*__KVCC_JS__*/", () => js)
  .replace("/*__KVCC_DEMO_JS__*/", () => demoJs)
  .replace("<!--__KVCC_FONTS__-->", `<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="${FONTS_URL}">`);
writeFileSync(join(dist, "kvcc-bundle.html"), page);

// Design-system reference page for the Artifact tool: component sections and the dialog are lifted from demo.html so there is one copy of the markup.
const between = (text, from, to) => text.slice(text.indexOf(from), text.lastIndexOf(to) + to.length);
const sections = between(demo, "<section", "</section>").replaceAll("<section ", '<section class="block" ');
const dialog = between(demo, "<div data-kv-dialog", "</div>\n\n<script>").replace(/\n\n<script>$/, "");
// Printed as text so a reader of the page gets the exact values (the swatches above it are computed at runtime). Comments are stripped to keep it short.
const escapeHtml = text => text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
// The tokens expect next/font or fontsource family names; Google Fonts serve "Inter" and "Geist", so the override is part of the printed CSS.
const printedCss = `${tokenCss}\n${fontOverride}`.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\n{2,}/g, "\n").trim();
const tokenText = escapeHtml(printedCss);
const designSystem = read(join(src, "design-system.html"))
  .replace("<!--__KVCC_TOKEN_CSS__-->", () => tokenText)
  .replace("/*__KVCC_CSS__*/", () => css.replace(fontImport + "\n\n", ""))
  .replace("/*__KVCC_JS__*/", () => js)
  .replace("/*__KVCC_DEMO_JS__*/", () => demoJs)
  .replace("<!--__KVCC_SECTIONS__-->", () => sections)
  .replace("<!--__KVCC_DIALOG__-->", () => dialog);
writeFileSync(join(dist, "design-system.html"), designSystem);

// Plain-text brief for tools that cannot open the artifact link: the same instructions and exact tokens, attachable or pasteable as one file.
const decode = text => text.replace(/<[^>]+>/g, "").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();
const steps = [...read(join(src, "design-system.html")).matchAll(/<li><strong>(.*?)<\/strong>(.*?)<\/li>/g)].filter(m => /^\d+\./.test(m[1])).map(m => `${decode(m[1])}\n${decode(m[2])}`);
writeFileSync(join(dist, "design-brief.md"), `# kvcc design system brief

Apply this system exactly when designing any screen. Do not approximate: use these variable names and values, not colors picked by eye. Light theme is the default; dark theme is \`data-theme="dark"\` on the root; the accent is \`data-accent\` (neutral, violet, blue, green, amber, orange, coral, rose).

## Rules

${steps.join("\n\n")}

## Token CSS

Paste this into the page as is, then style everything with the variables.

\`\`\`css
${printedCss}
\`\`\`

The last block of the CSS maps the font tokens to the plain family names \`Inter\` and \`Geist\`. Load them from Google Fonts (weights 400 and 500) under exactly those names, or the text silently falls back to the system font.
`);

// App template: a full-page starter (shell, stats, charts, table) for mini apps.
writeFileSync(join(dist, "template-app.html"), read(join(src, "template-app.html"))
  .replace("/*__KVCC_CSS__*/", () => css.replace(fontImport + "\n\n", ""))
  .replace("/*__KVCC_JS__*/", () => js)
  .replace("<!--__KVCC_FONTS__-->", `<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="${FONTS_URL}">`));

console.log(`bundle: ${COMPONENTS.length} components, css ${(css.length / 1024).toFixed(1)}KB, js ${(js.length / 1024).toFixed(1)}KB -> ${dist}`);
